    \label{MainThm2}
    \begin{enumerate}
    \item The classical limits of the quantum theta functions are the classical theta functions of \cite[Thm. 0.3]{GHKK}. 
    \item Let $\Theta_{\s{V}}^{\mathrm{mid}}\subset L_{\s{V}}$ be the set of $p$ such that $\vartheta_p$ is a Laurent polynomial (as opposed to merely a formal Laurent series). Then $\vartheta_p\in\s{V}_q^{\mathrm{up}}$ for $p\in \Theta_{\s{V}}^{\mathrm{mid}}$.  The set $\Theta_{\s{V}}^{\mathrm{mid}}$ is the same as in the corresponding classical cluster algebra setup of \cite[Thm. 0.3]{GHKK}.  In particular, $\Theta_{\s{V}}^{\mathrm{mid}}=\Theta^{\mathrm{mid}}_{\s{V},\bb{R}}\cap L_{\s{V}}$ for some cone $\Theta^{\mathrm{mid}}_{\s{V},\bb{R}}\subset L_{\s{V},\mathbb{R}}$ which is convex (but not necessarily strongly convex, rational polyhedral, or closed) and remains convex under the application of any of the piecewise-linear automorphisms $T_{\vec{\jmath}}^{\s{V}}$ of $L_{\s{V},\mathbb{R}}$ as defined in \eqref{mujj} and \eqref{TjX}.
    \item The theta functions $\{\vartheta_p\colon p\in \Theta_{\s{V}}^{\mathrm{mid}}\}$ form a ${\mathbb Z}_t$-module basis for the ${\mathbb Z}_t$-subalgebra $\s{V}_q^{\mathrm{mid}}$ of $\s{V}_q^{\mathrm{up}}$ which they generate.  Every global monomial is a theta function corresponding to some $p\in \Theta_{\s{V}}^{\mathrm{mid}}$, so we have the inclusions
    \begin{align*}
        \s{V}_q^{\mathrm{ord}} \subset \s{V}_q^{\mathrm{mid}} \subset \s{V}_q^{\mathrm{up}} 
        \subset \wh{\s{V}}_q^S.
    \end{align*}
    \item Let $\s{V}_q^{\mathrm{can}}$ denote the sub ${\mathbb Z}_t$-algebra of $\wh{\s{V}}_q^S$ generated by the theta functions.  The theta functions form a topological ${\mathbb Z}_t$-module basis for $\s{V}_q^{\mathrm{can}}$, and they form an ordinary ${\mathbb Z}_t$-module basis if and only if the corresponding classical theta functions form a ${\mathbb Z}$-module basis for the ${\mathbb Z}$-algebra $\s{V}^{\mathrm{can}}$ which they generate.  If $\s{V}_q$ has enough global monomials (cf. Definition \ref{EGMdef} --- this is equivalent to the corresponding condition in the classical setup up as in \cite[Def. 0.11]{GHKK}), then $\s{V}_q^{\mathrm{can}}$ is finitely generated over ${\mathbb Z}_t$, and each element of $\s{V}_q^{\mathrm{up}}$ is a finite $\bb{Z}_t$-linear combination of theta functions.  In particular, we then have $\s{V}_q^{\mathrm{up}} \subset \s{V}_q^{\mathrm{can}}$. 
    \item We have the equality $\s{V}_q^{\mathrm{mid}}=\s{V}_q^{\mathrm{can}}$, i.e., $\Theta_{\s{V}}^{\mathrm{mid}}=L_{\s{V}}$, if and only if the corresponding equality holds in the classical setting.  So if we furthermore have that $\s{V}_q$ has enough global monomials, then the full quantum Fock--Goncharov conjecture holds, by which we mean that $\s{V}_q^{\mathrm{mid}}=\s{V}_q^{\mathrm{up}}=\s{V}_q^{\mathrm{can}}$.
    \item Up to canonical isomorphism $\psi_{\vec{\jmath}}^{\s{V}}$, the ${\mathbb Z}_t$-algebras $\s{V}_q^{\mathrm{can}}$ and $\s{V}_q^{\mathrm{mid}}$ depend only on the mutation equivalence class of the initial seed, as do their theta functions (cf. Corollary \ref{TjCor} for the precise statement).  In addition, $\s{V}_q^{\mathrm{can}} \subset \wh{\s{V}}_q^{\mathrm{up}}$, the formal quantum upper cluster algebra defined in \S \ref{FormalUp}. 
    \item  The mutations $\upmu_{S,\vec{\jmath}}^{\s{V}}$ respect the $K_{\s{V}}$-gradings of $\wh{\s{V}}_q^S$ and $\wh{\s{V}}_q^{S_{\vec{\jmath}}}$ induced by $\kappa_{\s{V}}$, thus implying that we have a $K_{\s{V}}$-grading on $\s{V}_q^{\mathrm{up}}$.
    More generally, the adjoint action of any path-ordered product associated to $\f{D}^{\s{V}_q}$ (or $\s{D}^{\s{A}_q^{\mathrm{prin}}}$ when $\s{V}=\s{X}$) respects the $K_{\s{V}}$-grading on $\wh{\s{V}}_q^S$.  Furthermore, the theta functions are homogeneous with respect to the $K_{\s{V}}$-grading on $\wh{\s{V}}_q^S$.  
\item Suppose that $\Uplambda$ satisfies the compatibility condition \eqref{Lambda} for all $i\in I$ (not just $i\in I\setminus F$).  Then the map $B_1$ induces homomorphisms $B_1\colon \wh{\s{X}}_q^S\rar \wh{\s{A}}_q^S$ and $B_1\colon \s{X}_q^*\rar \s{A}_q^*$ for $*=\mathrm{ord}, \mathrm{mid}, \mathrm{up}$, or $\mathrm{can}$.  
Furthermore, for any $p\in L_{\s{X}}$, we have $B_1(\vartheta_p)=\vartheta_{B_1(p)}$. 
\item For $u\in H_{\s{V}}$, $p\in L_{\s{V}}$, and generic $\mathcal{Q} \in L_{\s{V},\bb{R}}$, we have $\upiota_{\mathcal{Q}}(\vartheta_{u+p})=\uptau_u(\upiota_{\mathcal{Q}}(\vartheta_p))$. In particular, for $u\in H_{\s{V}}$, $\upiota_{\mathcal{Q}}(\vartheta_u)=z^u$  for all generic $\mathcal{Q}$, and so $\vartheta_u\in \s{V}^{\mathrm{ord}}_q$.  
\end{enumerate}

