\begin{itemize}
    \item
    If $m_1=1$, we set $\upzeta(\pm)(1^{(1)})=M\pm\epsilon$ and $\upzeta(\pm)(2^{(1)})=-M$.
    \item
    If $m_1=0$ we set $\upzeta(\pm)(1^{(1)})=\pm \epsilon$.
    \item 
    If $m_2=1$, we set $\upzeta(\pm)(1^{(2)})=N$ and $\upzeta(\pm)(2^{(2)})=-N$.
    \item
    If $m_2=0$ we set $\upzeta(\pm)(1^{(2)})=0$.
\end{itemize}
Let $\upzeta$ be one of $\upzeta(\pm)$.  Let $\rho$ be a $\mathbb{C}Q$-module, with $\dim(\rho)\leq k$, satisfying the condition that each of the subquotients appearing in the Harder--Narasimhan filtration of $\rho$ with respect to the stability condition $\upzeta$ has slope contained in $I\coloneqq [-\updelta,\updelta]$.  Then in particular, $\rho$ has slope contained in $[-\updelta,\updelta]$.  It follows that if $Q^{(2)}$ is isomorphic to the Kronecker quiver, the restriction of the dimension vector of $\rho$ to $Q^{(2)}$ must be $(a,a)$ for some $a\in \mathbb{Z}_{\geq 0}$. Then the contribution of $Q^{(2)}$ to the slope of $\rho$ is zero, whichever quiver $Q^{(2)}$ is, and so if $Q^{(1)}$ is isomorphic to the Kronecker quiver, the restriction of the dimension vector of $\rho$ to $Q^{(1)}$ must be of the form $(b,b)$ for some $b\in\mathbb{Z}_{\geq 0}$.  

Let $\rho$ be a $\mathbb{C}Q$-module with $\dim(\rho)\leq k$, and with the dimension vector of $\rho$ constant after restriction to $Q^{(1)}$, and also constant after restriction to $Q^{(2)}$. We claim that the following are equivalent
\begin{enumerate}
    \item All of the subquotients appearing in the Harder--Narasimhan filtration of $\rho$ with respect to $\upzeta(-)$ have slope in $I$
    \item The restrictions $\rho^{(i)}$ of $\rho$ to $Q^{(i)}$ are $\upzeta(+)$ semistable for $i=1,2$
    \item All of the subquotients appearing in the Harder--Narasimhan filtration of $\rho$ with respect to $\upzeta(+)$ have slope in $I$.
\end{enumerate}
\begin{itemize}
    \item[$(1)\Leftrightarrow (2)$] The equivalence is trivial if one of $\rho^{(1)}$ or $\rho^{(2)}$ is trivial, so assume that they are both nontrivial.  So $\rho^{(2)}$ is a proper nontrivial submodule of $\rho$, and destabilizes it (for the stability condition $\upzeta(-)$).  In particular, picking $\rho'\subset\rho^{(2)}$ to be the maximal submodule to attain the maximal slope of a submodule of $\rho^{(2)}$, $\rho'$ is the maximal destabilizing submodule of $\rho$ and it has slope in $I$ if and only if $\rho^{(2)}$ is semistable (with respect to both stability conditions).  Similarly, the maximal destabilizing quotient of $\rho$ with respect to $\upzeta(-)$ is a quotient of $\rho^{(1)}$, and it has slope in $I$ if and only if $\rho^{(1)}$ is semistable with respect to both stability conditions.
    \item[$(3)\Rightarrow (2)$] If $\rho'\subset \rho^{(2)}$ was a destabilizing submodule with respect to $\upzeta(+)$, it would also be a submodule of $\rho$ with $\upzeta(+)$-slope greater than $\updelta$, which is impossible by the condition on $\rho$.  Similarly, if $\rho'\subset \rho^{(1)}$ was destabilizing, then $\rho'\oplus \rho^{(2)}$, with its natural $\mathbb{C}Q$-module structure, would have slope greater than $\updelta$.  So we deduce that both $\rho^{(1)}$ and $\rho^{(2)}$ are semistable.
    \item[$(2)\Rightarrow (3)$] Say that $\rho^{(1)}$ and $\rho^{(2)}$ are semistable.  Let $\rho'\subset \rho$ be the maximal destabilizing submodule with respect to the stability condition $\upzeta(+)$, i.e. the first non-trivial term in the Harder--Narasimhan filtration of $\rho$.  If $Q^{(2)}$ is isomorphic to the Kronecker quiver, let $(a,b)$ be the dimension vector of $\rho'$ restricted to $Q^{(2)}$.  Since this restriction is a submodule of $\rho^{(2)}$ we must have $a\leq b$.  On the other hand, since $\rho'$ destabilizes $\rho$ we must have $a\geq b$.  We deduce that $a=b$, and so whichever quiver $Q^{(2)}$ is, the contribution of $Q^{(2)}$ to the slope of $\rho'$ is zero.  Now assume that $Q^{(1)}$ is isomorphic to the Kronecker quiver.  By the same argument, the dimension vector of $\rho'$, restricted to $Q^{(1)}$, must be constant.  We deduce that the slope of $\rho'$ lies within $I$.  Applying the same argument to $\rho/\rho'$, we see that the slope of all the subquotients in the Harder--Narasimhan filtration of $\rho$ belong to $I$.
\end{itemize}

From $(1)\Leftrightarrow (3)$ we deduce that
\begin{equation}
\label{zeta_ind}
\mathfrak{M}^{\upzeta(+)}_I(Q)=\mathfrak{M}^{\upzeta(-)}_I(Q).
\end{equation}

Consider the case in which $Q^{(1)}$ is the single vertex quiver, and write $e\in K$ for the generator corresponding to the vertex $1^{(1)}$.  We have
\[
\upchi_{\mathrm{wt},K}\left(\bigoplus_{v\in \mathbb{Z}_{\geq 0}\cdot e}\mathrm{H}_c(\mathfrak{M}^{\upzeta(\pm)-sst}_{v}(Q))_{\mathrm{vir}}^*\right)=\mathbb{E}(x^{e})
\]
by (\ref{ref_ferm}).

Now consider the case in which $Q^{(1)}$ is isomorphic to the Kronecker quiver.  Write $e$ for the sum of the generators in $K$ corresponding to the vertices $1^{(1)}$ and $2^{(1)}$.  Then by (\ref{ref_Kron}) we have
\[
\upchi_{\mathrm{wt},K}\left(\bigoplus_{v\in \mathbb{Z}_{\geq 0}\cdot e}\mathrm{H}_c(\mathfrak{M}^{\upzeta(\pm)-sst}_{v}(Q))_{\mathrm{vir}}^*\right)=\mathbb{E}(x^{e}[2]_t).
\]
The same results hold for $Q^{(2)}$; we let $f$ denote the element in $K$ defined analogously to $e$ but for $Q^{(2)}$.  Applying (\ref{GrandForm}) with $\upzeta=\upzeta(-)$ we deduce that
\begin{equation}
\label{half_one}    
\uppi\hspace{0.05em}\left(\upchi_{\mathrm{wt},K}\left(\bigoplus_{v\in K}\mathrm{H}_c(\mathfrak{M}^{\upzeta(-)}_{I,v}(Q),\mathbb{Q})^*_{\mathrm{vir}}\right)\right)=\uppi\hspace{0.05em}\left(\mathbb{E}([m_2+1]_tx^f)\mathbb{E}([m_1+1]_tx^e)\right).
\end{equation}
Now for the stability condition $\upzeta(+)$ there may be more semistable modules with slope contained in $I$, but they must have dimension vector of the form $\upalpha e+\upbeta f$ for $\upalpha,\upbeta\in \mathbb{Z}_{>0}$.  Applying (\ref{GrandForm}) again, we deduce that 
\begin{align}
\label{half_two}
&\uppi\hspace{0.05em}\left(\upchi_{\mathrm{wt},K}\left(\bigoplus_{v\in K}\mathrm{H}_c(\mathfrak{M}^{\upzeta(+)}_{I,v}(Q),\mathbb{Q})^*_{\mathrm{vir}}\right)\right)=\\&\uppi\hspace{0.05em}\left(\mathbb{E}([m_1+1]_tx^e)\prod_{\substack{0\xrightarrow{\upbeta/\upalpha}\infty\\\upalpha\neq 0,\upbeta\neq 0}}\mathbb{E}(\upchi_{\mathrm{wt}}(\mathrm{BPS}^{\upzeta(+)}_{\upalpha e+\upbeta f}(Q))x^{\upalpha e+\upbeta f}) \mathbb{E}([m_2+1]_tx^f)\right).\nonumber
\end{align}
Combining (\ref{zeta_ind}), (\ref{half_one}), and (\ref{half_two}), we deduce that 
\begin{align}
\label{two_halves}
&\uppi\hspace{0.05em}\left(\mathbb{E}([m_2+1]_tx^f)\mathbb{E}([m_1+1]_tx^e)\right)=\\&\uppi\hspace{0.05em}\left(\mathbb{E}([m_1+1]_tx^e)\prod_{\substack{0\xrightarrow{\upbeta/\upalpha}\infty\\\upalpha\neq 0,\upbeta\neq 0}}\mathbb{E}(\upchi_{\mathrm{wt}}(\mathrm{BPS}^{\upzeta(+)}_{\upalpha e+\upbeta f}(Q))x^{\upalpha e+\upbeta f})\nonumber \mathbb{E}([m_2+1]_tx^f)\right).
\end{align}
Note that $\mathrm{BPS}_{\upalpha e+\upbeta f}^{\upzeta(+)}$ is independent of the large $M,N$ we pick in the above argument.  We denote this mixed Hodge structure instead by $\mathrm{BPS}_{\upalpha e+\upbeta f}^{\lim}$.  In particular, it does not depend on $k$.  Letting $k$ tend to infinity, in the limit (\ref{two_halves}) becomes
\begin{align}
\label{two_halves_two}
\mathbb{E}([m_2+1]_tx^f)\mathbb{E}([m_1+1]_tx^e)=\mathbb{E}([m_1+1]_tx^e)\prod_{\substack{0\xrightarrow{\upbeta/\upalpha}\infty\\\upalpha\neq 0,\upbeta\neq 0}}\mathbb{E}(\upchi_{\mathrm{wt}}(\mathrm{BPS}^{\lim}_{\upalpha e+\upbeta f}(Q))x^{\upalpha e+\upbeta f}) \mathbb{E}([m_2+1]_tx^f).
\end{align}

By Corollary \ref{MRcor}, each term $\mathbb{E}(\upchi_{\mathrm{wt}}(\mathrm{BPS}^{\lim}_{\upalpha e+\upbeta f}(Q))x^{\upalpha e+\upbeta f})$ is of Lefschetz type, and so is of pL type.  Note that $x^ex^f=t^nx^{e+f}$.  Let $\hat{\mathfrak{g}}^{\circ}\subset \hat{\mathfrak{g}}_{Q}$ be the sub Lie algebra obtained by taking the closure of the span of the elements $\hat{x}^{g}$ for $g=\upalpha e+ \upbeta f$, with $\upalpha,\upbeta\in\mathbb{Z}_{\geq 0}$ and $\upalpha+\upbeta>0$.  Denote by $L'$ the lattice spanned by $v_1$ and $v_2$.  There is an isomorphism of Lie algebras $\hat{\mathfrak{g}}^{\circ}\rightarrow \mathfrak{g}_{L'^+,\omega}$ sending $\hat{x}^{\upalpha e+\upbeta f}$ to $\hat{z}^{\upalpha v_1+ \upbeta v_2}$.  Exponentiating, we obtain an isomorphism of pro-unipotent algebraic groups
\[
\Phi\colon \hat{G}^{\circ}\xrightarrow{\cong}\hat{G}_{L'}.
\]

Finally, we use the identity \eqref{two_halves_two} to construct $\f{D}$.  Let $V=v_1^{\omega\perp}\cap v_2^{\omega\perp}$.  From $\omega(v_1,v_2)\neq 0$ and $v_{i}\in v_{i}^{\omega\perp}$ it follows that $V$ has codimension 2.  We define $\f{D}$ to be the scattering diagram containing $\f{D}_{\mathrm{in}}$ as well as a wall
\begin{align}\label{Dout}
(V-\bb{R}_{\geq 0}\cdot (\upalpha v_1+\upbeta v_2),\mathbb{E}(-\upchi_{\mathrm{wt}}(\mathrm{BPS}^{\lim}_{\upalpha e+\upbeta f}(Q))z^{\upalpha v_1+\upbeta v_2}))
\end{align}
for each $\upalpha,\upbeta\in\mathbb{Z}_{>0}$.  Then $V$ is the only joint in $\f{D}$, and consistency around this joint amounts to the equality
\begin{align}\label{PL_eq}
\mathbb{E}(-[m_1+1]_tz^{v_{1}})&\mathbb{E}(-[m_2+1]_tz^{v_{2}})\\\nonumber=&\mathbb{E}(-[m_2+1]_tz^{v_2})\prod_{\substack{\infty \xrightarrow{\upbeta/\upalpha}0\\\upalpha\neq 0,\upbeta\neq 0}}\mathbb{E}(-\upchi_{\mathrm{wt}}(\mathrm{BPS}^{\lim}_{\upalpha e+\upbeta f}(Q))z^{\upalpha v_1+\upbeta v_2}) \mathbb{E}(-[m_1+1]_tz^{v_1}),
\end{align}
cf. Figure \ref{PL_fig} where this corresponds to the equality of $\uptheta_{\upgamma_1,\f{D}}$ and $\uptheta_{\upgamma_2,\f{D}}$.  Finally, \eqref{PL_eq} follows from applying $\Phi$ to \eqref{two_halves_two} and inverting each side. 
